      albums_delete_desc_perm_warn_singular: "எச்சரிக்கை: இந்த ஆல்பத்தில் உள்ள 1 புகைப்படம் உங்கள் ஆர்கனைசர் மற்றும் சாதன சேமிப்பகத்திலிருந்து நிரந்தரமாக அழிக்கப்படும். இது குப்பைத்தொட்டிக்கு நகர்த்தப்படாது.",
      albums_delete_desc_perm_warn_plural: "எச்சரிக்கை: இந்த ஆல்பத்தில் உள்ள அனைத்து {count} புகைப்படங்களும் உங்கள் ஆர்கனைசர் மற்றும் சாதன சேமிப்பகத்திலிருந்து நிரந்தரமாக அழிக்கப்படும். அவை குப்பைத்தொட்டிக்கு நகர்த்தப்படாது.",
