      feedback_toast_queued: 'ਫੀਡਬੈਕ ਸੁਰੱਖਿਅਤ ਸੇਵ ਹੋ ਗਿਆ। ਜੁੜਨ \'ਤੇ ਫਾਇਰਬੇਸ ਨਾਲ ਸਿੰਕ ਹੋਵੇਗਾ।',



      detail_rename: 'ਨਾਮ ਬਦਲੋ',
